const item = $input.first();
let content = '';

try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  content = buf.toString('utf8');
} catch(e) {
  return [{ json: { err_msg: 'binary read fail: ' + e.message } }];
}

let kbArr = [];
try {
  const parsed = JSON.parse(content);
  kbArr = Array.isArray(parsed) ? parsed : [];
} catch(e) {
  return [{ json: { err_msg: 'json parse fail: ' + e.message } }];
}

const rawText = $('When Message Received').item.json.message.text || '';
const question = rawText.replace('/ask ', '').trim();

return [{ json: { kb_data: kbArr, question: question } }];

const input = $input.first().json;

if (!input.question || !input.kb_data) {
  return [{ json: { context: 'no data available', question: '' } }];
}

const q = input.question.toLowerCase().split(' ');
const kb = input.kb_data;

if (!Array.isArray(kb) || kb.length === 0) {
  return [{ json: { context: 'empty db', question: input.question } }];
}

let scored = kb.map(chunk => {
  let score = 0;
  let txt = (chunk.text || chunk.content || '').toLowerCase();

  q.forEach(word => {
    if (txt.includes(word) && word.length > 2) score++;
  });

  return { txt: txt, score: score };
});

scored.sort((a, b) => b.score - a.score);

let top = scored.slice(0, 2).map(s => s.txt).join('\n---\n');

if (!top) top = 'no match';

return [{ json: { context: top, question: input.question } }];

