let output = '';

try {
  output = $input.first().json.output || $input.first().json.text || '';
} catch(e) {
  output = '';
}

output = output.replace(/&lt;think&gt;[\s\S]*?<\/think>/gi, '').trim();
output = output.replace(/<[^>]+>/g, '').trim();

if (!output) {
  output = 'I could not generate an answer. Please try rephrasing your question.';
}

return [{ json: { output: output } }];

let txt = $input.first().json.output || '';
txt = txt.replace(/<thinking>[\s\S]*?<\/thinking>/gi, '').trim();
txt = txt.replace(/<\/?[^>]+(>|$)/g, '').trim();

if (txt.length > 3800) {
  txt = txt.substring(0, 3797) + '...';
}

if (txt.length > 0) {
  txt = txt.charAt(0).toUpperCase() + txt.slice(1);
}

txt += '\n\n—\nPowered by Vinh Automation | vinhautomation.com/en';

return [{ json: { final_text: txt } }];
